from .exceptions import InvalidPythonVersionException


class ProxyMngrValidator:

    @staticmethod
    def validate_python_version(python_version):
        """
        Validate proxy mngr python version

        :param python_version: python version used to deploy proxy manager
        :raise InvalidPythonVersion: If python version is not str type or length is not equal 2 or 3
        :return:
        """
        if not isinstance(python_version, str):
            raise InvalidPythonVersionException("Python version should be stored as str type! "
                                                f"Current type: {type(python_version)}")
        elif len(python_version) not in [2, 3]:
            raise InvalidPythonVersionException("Python version should contain only major and minor version")
        else:
            try:
                int(python_version)
            except ValueError:
                raise InvalidPythonVersionException("Python version should contain only digits")
